import React from 'react';

export interface EventGoogleFormPanelProps {
  customGoogleFormUrl: string;
  embedUrl: string;
  showUrlInput: boolean;
  onGoogleFormUrlChange: (url: string) => void;
}

export const EventGoogleFormPanel: React.FC<EventGoogleFormPanelProps> = ({
  customGoogleFormUrl,
  embedUrl,
  showUrlInput,
  onGoogleFormUrlChange
}) => {
  return (
    <div className="tool-panel">
      <div className="flex-between">
        <div>
          <h2 className="tool-panel-title">Write-Only Google Form Intake</h2>
          <p className="tool-panel-subtitle">
            Submit event requests directly via Google Forms. Fields can be edited anytime in Google Forms, and the attached Google Apps Script automatically formats the Event JSON and emails it without exposing any email address.
          </p>
        </div>
        {customGoogleFormUrl.trim() && (
          <a
            href={customGoogleFormUrl.trim()}
            target="_blank"
            rel="noopener noreferrer"
            className="btn btn-primary btn-sm"
          >
            Open Google Form in New Tab ↗
          </a>
        )}
      </div>

      {showUrlInput && (
        <div className="tool-field-group">
          <label htmlFor="gf-url-input" className="tool-label">
            Google Form URL (Published <code>viewform</code> Link)
          </label>
          <span id="gf-url-hint" className="tool-hint">
            Set <code>VITE_EVENT_REQUEST_GOOGLE_FORM_URL</code> in <code>tools/website/.env</code> or paste your published Google Form link below
          </span>
          <input
            id="gf-url-input"
            type="url"
            className="tool-input"
            value={customGoogleFormUrl}
            onChange={(e) => onGoogleFormUrlChange(e.target.value)}
            placeholder="https://docs.google.com/forms/d/e/.../viewform"
            autoCorrect="off"
            autoCapitalize="off"
            spellCheck={false}
            aria-describedby="gf-url-hint"
          />
        </div>
      )}

      {embedUrl ? (
        <iframe
          src={embedUrl}
          title="CEGAANA New Event Request Google Form"
          className="tool-iframe-frame"
        >
          Loading Google Form...
        </iframe>
      ) : (
        <div className="tool-status-banner tool-status-info">
          No Google Form URL is currently configured. Paste a published Google Form link above, or use the <strong>🛠️ Interactive Event JSON Builder</strong> tab.
        </div>
      )}
    </div>
  );
};

