import { ToolsHubPage } from '../pages/ToolsHubPage.js';
import { QrGeneratorToolPage } from '../pages/QrGeneratorToolPage.js';
import { EventRequestToolPage } from '../pages/EventRequestToolPage.js';
import type { RouteDefinition } from './types.js';

/**
 * Sub-routes for the unindexed /p/tools operational utilities section.
 * Keys are relative to the `/p/tools` prefix (e.g. '' for /p/tools, 'qr' for /p/tools/qr).
 */
export const toolsSubRoutes: Record<string, RouteDefinition> = {
  '': {
    component: ToolsHubPage,
    title: 'Operational Tools | CEGAANA',
    description: 'Internal and volunteer operational utilities for generating branded CEGAANA QR codes and structured event requests.',
    ogType: 'website',
    noIndex: true,
  },
  'qr': {
    component: QrGeneratorToolPage,
    title: 'Branded QR Code Generator | CEGAANA Tools',
    description: 'Generate print-ready 880 × 1055 px branded CEGAANA QR cards and standalone vector QR codes.',
    ogType: 'website',
    noIndex: true,
  },
  'event-request': {
    component: EventRequestToolPage,
    title: 'New Event Request & JSON Generator | CEGAANA Tools',
    description: 'Author structured event details, generate ready-to-publish events.json payloads, and submit write-only event requests.',
    ogType: 'website',
    noIndex: true,
  },
};

/**
 * Resolve a sub-path within the /p/tools domain.
 * @param subPath The path relative to /p/tools, with leading/trailing slashes trimmed.
 */
export function resolveToolsRoute(subPath: string): RouteDefinition | undefined {
  return toolsSubRoutes[subPath];
}

