import { ConvergeOverviewPage } from '../pages/ConvergeOverviewPage.js';
import { Converge2026Page } from '../pages/Converge2026Page.js';
import { LeadersForumPage } from '../pages/LeadersForumPage.js';
import type { RouteDefinition } from './types.js';

/**
 * Sub-routes for the /converge conference domain.
 * Keys are relative to `/converge` (e.g. '' for /converge, '2026' for /converge/2026, '2026/lf' for /converge/2026/lf).
 */
export const convergeSubRoutes: Record<string, RouteDefinition> = {
  '': {
    component: ConvergeOverviewPage,
    title: 'CEG Converge Conference Series | CEGAANA',
    description: 'CEG Converge North American alumni conference series. Milestone recap of Converge 2026 and roadmap for Dallas 2027 and Seattle 2028.',
    ogType: 'website',
  },
  '2026': {
    component: Converge2026Page,
    title: 'CEG Converge 2026 | Alumni Conference Portal',
    description: 'CEG Converge 2026 - Join hundreds of College of Engineering Guindy alumni, founders, and students in Santa Clara, CA for keynote sessions, networking, and celebration.',
    ogType: 'website',
  },
  '2026/lf': {
    component: LeadersForumPage,
    title: 'CEG Leaders Forum 2026 | Executive Alumni Summit',
    description: 'Executive leadership summit bringing together industry pioneers, venture leaders, and distinguished alumni for high-impact panel discussions.',
    ogType: 'website',
  },
};



/**
 * Resolve a sub-path within the /converge domain.
 * @param subPath The path relative to /converge, with leading/trailing slashes trimmed.
 */
export function resolveConvergeRoute(subPath: string): RouteDefinition | undefined {
  return convergeSubRoutes[subPath];
}
