import React, { useState, useEffect } from 'react';
import type { PageProps } from './types.js';
import { Breadcrumb, Badge } from '../components/common/index.js';
import {
  QR_THEME_PRESETS,
  generateBrandedQrCardSvg,
  generateQrSvg,
  svgToDataUri,
  copySvgAsPngToClipboard,
  downloadQrAsset,
  type QrThemePreset
} from '../utils/qrGenerator.js';

export const QrGeneratorToolPage: React.FC<PageProps> = ({ onNavigate }) => {
  const [mode, setMode] = useState<'branded' | 'plain'>('branded');
  const [url, setUrl] = useState<string>('https://forms.gle/mS4FAjrm1h3Tbzaa9');
  const [label, setLabel] = useState<string>('CEGAANA Feedback Form');
  const [outerBg, setOuterBg] = useState<string>('#2b7431');
  const [badgeTextColor, setBadgeTextColor] = useState<string>('#215926');
  const [badgeBg, setBadgeBg] = useState<string>('#ffd978');
  const [fontSize, setFontSize] = useState<number>(50);
  const [errorCorrection, setErrorCorrection] = useState<'L' | 'M' | 'Q' | 'H'>('M');
  const [activePresetId, setActivePresetId] = useState<string>('feedback-green');

  const [svgMarkup, setSvgMarkup] = useState<string>('');
  const [statusMessage, setStatusMessage] = useState<{ type: 'success' | 'error' | 'info'; text: string } | null>(null);

  useEffect(() => {
    let cancelled = false;
    const targetUrl = url.trim() || 'https://cegaana.org';

    const renderQr = async () => {
      try {
        if (mode === 'branded') {
          const svg = await generateBrandedQrCardSvg(targetUrl, {
            label: label.trim() || 'CEGAANA',
            outerBg,
            badgeBg,
            badgeTextColor,
            fontSize,
            errorCorrectionLevel: errorCorrection
          });
          if (!cancelled) setSvgMarkup(svg);
        } else {
          const svg = await generateQrSvg(targetUrl, {
            errorCorrectionLevel: errorCorrection,
            margin: 4,
            width: 880,
            darkColor: '#000000',
            lightColor: '#ffffff'
          });
          if (!cancelled) setSvgMarkup(svg);
        }
      } catch (err) {
        if (!cancelled) {
          setStatusMessage({
            type: 'error',
            text: `QR generation error: ${err instanceof Error ? err.message : String(err)}`
          });
        }
      }
    };

    renderQr();
    return () => {
      cancelled = true;
    };
  }, [mode, url, label, outerBg, badgeBg, badgeTextColor, fontSize, errorCorrection]);

  const applyPreset = (preset: QrThemePreset, includeSampleContent: boolean) => {
    setActivePresetId(preset.id);
    setOuterBg(preset.outerBg);
    setBadgeTextColor(preset.badgeTextColor);
    setBadgeBg(preset.badgeBg);
    setFontSize(preset.fontSize);
    if (includeSampleContent) {
      setLabel(preset.sampleLabel);
      setUrl(preset.sampleUrl);
    }
  };

  const canvasWidth = 880;
  const canvasHeight = mode === 'branded' ? 1055 : 880;
  const filenameBase = mode === 'branded'
    ? `${label.trim() || 'CEGAANA'}-QRCode`
    : 'CEGAANA-Plain-QRCode';

  const handleCopyImage = async () => {
    if (!svgMarkup) return;
    try {
      await copySvgAsPngToClipboard(svgMarkup, canvasWidth, canvasHeight);
      setStatusMessage({
        type: 'success',
        text: `✓ Copied ${canvasWidth} × ${canvasHeight} px PNG image to clipboard!`
      });
    } catch (err) {
      setStatusMessage({
        type: 'error',
        text: `Could not copy image to clipboard: ${err instanceof Error ? err.message : String(err)}`
      });
    }
  };

  const handleCopySvg = async () => {
    if (!svgMarkup) return;
    try {
      await navigator.clipboard.writeText(svgMarkup);
      setStatusMessage({
        type: 'success',
        text: '✓ Copied vector SVG markup to clipboard!'
      });
    } catch (err) {
      setStatusMessage({
        type: 'error',
        text: `Could not copy SVG markup: ${err instanceof Error ? err.message : String(err)}`
      });
    }
  };

  const handleDownload = async (format: 'jpeg' | 'png' | 'svg') => {
    if (!svgMarkup) return;
    try {
      await downloadQrAsset(svgMarkup, filenameBase, format, canvasWidth, canvasHeight);
      setStatusMessage({
        type: 'info',
        text: `📥 Downloaded ${filenameBase}.${format === 'jpeg' ? 'jpg' : format}`
      });
    } catch (err) {
      setStatusMessage({
        type: 'error',
        text: `Download failed: ${err instanceof Error ? err.message : String(err)}`
      });
    }
  };

  return (
    <div>
      <header className="tool-topbar">
        <div className="container tool-topbar-inner">
          <div className="tool-topbar-left">
            <h1 className="tool-topbar-title">📱 Branded QR Code Generator</h1>
            <p className="tool-topbar-subtitle">
              Create 880 × 1055 px branded CEGAANA QR cards or standalone vector QR codes.
            </p>
          </div>
          <button
            type="button"
            className="btn btn-hero-outline btn-sm"
            onClick={(e) => onNavigate('/p/tools', e)}
          >
            ← All Tools
          </button>
        </div>
      </header>

      <section className="section-sm section-muted">
        <div className="container">
          <Breadcrumb
            items={[
              { label: 'Home', path: '/' },
              { label: 'Operational Tools', path: '/p/tools' },
              { label: 'QR Code Generator' }
            ]}
            onNavigate={onNavigate}
          />

          <div className="tool-workspace-grid">
            {/* Left Column: Configuration Controls */}
            <div className="tool-panel">
              <h2 className="tool-panel-title">QR Code Configuration</h2>
              <p className="tool-panel-subtitle">
                Customize the destination URL, action badge label, and brand theme colors.
              </p>

              <form onSubmit={(e) => e.preventDefault()}>
                <fieldset className="tool-fieldset">
                  <legend className="tool-legend">1. Output Layout Mode &amp; Destination</legend>

                  <div className="tool-field-group">
                    <span className="tool-label">Layout Style</span>
                    <div className="tool-radio-group" role="radiogroup" aria-label="QR Code Layout Style">
                      <label className="tool-radio-pill">
                        <input
                          type="radio"
                          name="qrMode"
                          value="branded"
                          checked={mode === 'branded'}
                          onChange={() => setMode('branded')}
                        />
                        <span>Branded CEGAANA Card (880 × 1055 px)</span>
                      </label>
                      <label className="tool-radio-pill">
                        <input
                          type="radio"
                          name="qrMode"
                          value="plain"
                          checked={mode === 'plain'}
                          onChange={() => setMode('plain')}
                        />
                        <span>Plain Square QR Only (880 × 880 px)</span>
                      </label>
                    </div>
                  </div>

                  <div className="tool-field-group">
                    <label htmlFor="qr-target-url" className="tool-label">
                      Destination URL *
                    </label>
                    <span id="qr-url-hint" className="tool-hint">
                      Full HTTPS link encoded in the QR matrix (Google Form, Stripe link, Zoom, or cegaana.org page).
                    </span>
                    <input
                      id="qr-target-url"
                      name="targetUrl"
                      type="url"
                      required
                      className="tool-input"
                      value={url}
                      onChange={(e) => setUrl(e.target.value)}
                      placeholder="https://forms.gle/..."
                      autoCorrect="off"
                      autoCapitalize="off"
                      spellCheck={false}
                      aria-describedby="qr-url-hint"
                    />
                    <div className="tool-error-msg">
                      <span aria-hidden="true">❌</span> Please enter a valid URL starting with https:// or http://.
                    </div>
                  </div>

                  <div className="tool-field-group">
                    <span className="tool-label">Error Correction Level</span>
                    <span className="tool-hint">
                      Level M (15%) is the CEGAANA standard for print flyers and signage.
                    </span>
                    <div className="tool-radio-group" role="radiogroup" aria-label="Error Correction Level">
                      {(['L', 'M', 'Q', 'H'] as const).map((lvl) => (
                        <label key={lvl} className="tool-radio-pill">
                          <input
                            type="radio"
                            name="errorCorrection"
                            value={lvl}
                            checked={errorCorrection === lvl}
                            onChange={() => setErrorCorrection(lvl)}
                          />
                          <span>Level {lvl}{lvl === 'M' ? ' (Standard)' : ''}</span>
                        </label>
                      ))}
                    </div>
                  </div>
                </fieldset>

                {mode === 'branded' && (
                  <fieldset className="tool-fieldset">
                    <legend className="tool-legend">2. Branded Card &amp; Badge Styling</legend>

                    <div className="tool-field-group">
                      <span className="tool-label">CEGAANA Color Presets</span>
                      <span className="tool-hint">
                        Click a preset to apply its brand palette (double-click to also fill sample label &amp; URL).
                      </span>
                      <div className="tool-preset-grid">
                        {QR_THEME_PRESETS.map((preset) => (
                          <button
                            key={preset.id}
                            type="button"
                            className={`tool-preset-btn ${activePresetId === preset.id ? 'tool-preset-btn-active' : ''}`}
                            onClick={() => applyPreset(preset, false)}
                            onDoubleClick={() => applyPreset(preset, true)}
                          >
                            <span aria-hidden="true">🎨</span>
                            <span>{preset.name}</span>
                          </button>
                        ))}
                      </div>
                    </div>

                    <div className="tool-field-row-2">
                      <div>
                        <label htmlFor="qr-badge-label" className="tool-label">
                          Action Badge Label *
                        </label>
                        <span id="qr-label-hint" className="tool-hint">
                          Bold centered text inside the dashed tan badge panel.
                        </span>
                        <input
                          id="qr-badge-label"
                          name="badgeLabel"
                          type="text"
                          required
                          maxLength={38}
                          className="tool-input"
                          value={label}
                          onChange={(e) => setLabel(e.target.value)}
                          placeholder="CEGAANA Feedback Form"
                          aria-describedby="qr-label-hint"
                        />
                      </div>

                      <div>
                        <label htmlFor="qr-font-size" className="tool-label">
                          Label Font Size ({fontSize} px)
                        </label>
                        <span id="qr-fontsize-hint" className="tool-hint">
                          Standard: 50–54 px (reduce for longer labels).
                        </span>
                        <input
                          id="qr-font-size"
                          name="fontSize"
                          type="range"
                          min={28}
                          max={64}
                          step={2}
                          className="tool-input"
                          value={fontSize}
                          onChange={(e) => setFontSize(Number(e.target.value))}
                          aria-describedby="qr-fontsize-hint"
                        />
                      </div>
                    </div>

                    <div className="tool-field-row-3">
                      <div>
                        <label htmlFor="qr-outer-bg" className="tool-label">
                          Outer Card Fill
                        </label>
                        <div className="tool-color-input-wrap">
                          <input
                            id="qr-outer-bg-picker"
                            type="color"
                            className="tool-color-picker"
                            value={outerBg}
                            onChange={(e) => {
                              setOuterBg(e.target.value);
                              setActivePresetId('custom');
                            }}
                            aria-label="Outer Card Fill Color Picker"
                          />
                          <input
                            id="qr-outer-bg"
                            type="text"
                            className="tool-input"
                            value={outerBg}
                            onChange={(e) => {
                              setOuterBg(e.target.value);
                              setActivePresetId('custom');
                            }}
                            autoCorrect="off"
                            autoCapitalize="off"
                            spellCheck={false}
                          />
                        </div>
                      </div>

                      <div>
                        <label htmlFor="qr-text-color" className="tool-label">
                          Badge Label Color
                        </label>
                        <div className="tool-color-input-wrap">
                          <input
                            id="qr-text-color-picker"
                            type="color"
                            className="tool-color-picker"
                            value={badgeTextColor}
                            onChange={(e) => {
                              setBadgeTextColor(e.target.value);
                              setActivePresetId('custom');
                            }}
                            aria-label="Badge Label Color Picker"
                          />
                          <input
                            id="qr-text-color"
                            type="text"
                            className="tool-input"
                            value={badgeTextColor}
                            onChange={(e) => {
                              setBadgeTextColor(e.target.value);
                              setActivePresetId('custom');
                            }}
                            autoCorrect="off"
                            autoCapitalize="off"
                            spellCheck={false}
                          />
                        </div>
                      </div>

                      <div>
                        <label htmlFor="qr-badge-bg" className="tool-label">
                          Badge Panel Fill
                        </label>
                        <div className="tool-color-input-wrap">
                          <input
                            id="qr-badge-bg-picker"
                            type="color"
                            className="tool-color-picker"
                            value={badgeBg}
                            onChange={(e) => {
                              setBadgeBg(e.target.value);
                              setActivePresetId('custom');
                            }}
                            aria-label="Badge Panel Fill Color Picker"
                          />
                          <input
                            id="qr-badge-bg"
                            type="text"
                            className="tool-input"
                            value={badgeBg}
                            onChange={(e) => {
                              setBadgeBg(e.target.value);
                              setActivePresetId('custom');
                            }}
                            autoCorrect="off"
                            autoCapitalize="off"
                            spellCheck={false}
                          />
                        </div>
                      </div>
                    </div>
                  </fieldset>
                )}
              </form>
            </div>

            {/* Right Column: Live Preview & Export Actions */}
            <div className="tool-panel tool-panel-sticky">
              <div className="flex-between">
                <h2 className="tool-panel-title">Live Asset Preview</h2>
                <Badge variant="success">
                  {canvasWidth} × {canvasHeight} px
                </Badge>
              </div>
              <p className="tool-panel-subtitle">
                Copy directly to your clipboard or download for print and web use.
              </p>

              <div className="qr-preview-stage">
                {svgMarkup ? (
                  <img
                    src={svgToDataUri(svgMarkup)}
                    alt={`QR Code for ${label || url}`}
                    className="qr-preview-img"
                  />
                ) : (
                  <p className="tool-hint">Rendering QR preview...</p>
                )}
              </div>

              <button
                type="button"
                className="btn btn-primary btn-full btn-lg"
                onClick={handleCopyImage}
              >
                📋 Copy Image to Clipboard (PNG)
              </button>

              <div className="tool-actions-grid">
                <button
                  type="button"
                  className="btn btn-secondary btn-sm"
                  onClick={() => handleDownload('jpeg')}
                >
                  📥 Download JPG (95%)
                </button>
                <button
                  type="button"
                  className="btn btn-secondary btn-sm"
                  onClick={() => handleDownload('png')}
                >
                  📥 Download PNG
                </button>
                <button
                  type="button"
                  className="btn btn-outline btn-sm"
                  onClick={() => handleDownload('svg')}
                >
                  📥 Download SVG
                </button>
                <button
                  type="button"
                  className="btn btn-outline btn-sm"
                  onClick={handleCopySvg}
                >
                  📋 Copy SVG Code
                </button>
              </div>

              {statusMessage && (
                <div
                  className={`tool-status-banner tool-status-${statusMessage.type}`}
                  role="status"
                  aria-live="polite"
                >
                  {statusMessage.text}
                </div>
              )}
            </div>
          </div>
        </div>
      </section>
    </div>
  );
};
