import React, { useRef } from 'react';
import {
  getCanonicalFlyerPaths,
  type EventRequestFormState,
  type FlyerUploadData
} from '../../utils/eventRequestBuilder.js';

export interface EventLogisticsSectionProps {
  formData: EventRequestFormState;
  computedSlug: string;
  normalizedIso: string;
  tzCombinedLabel?: string;
  flyerUpload: FlyerUploadData | null;
  flyerError: string | null;
  onChange: (updates: Partial<EventRequestFormState>) => void;
  onFlyerSelect: (file: File | null) => void;
}

export const EventLogisticsSection: React.FC<EventLogisticsSectionProps> = ({
  formData,
  computedSlug,
  normalizedIso,
  tzCombinedLabel,
  flyerUpload,
  flyerError,
  onChange,
  onFlyerSelect
}) => {
  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const { filename: targetFilename, assetPath: targetAssetPath } = getCanonicalFlyerPaths(
    computedSlug || formData.title || 'new-cegaana-event'
  );

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0] || null;
    onFlyerSelect(file);
  };

  const handleRemoveFlyer = () => {
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
    onFlyerSelect(null);
  };

  const handleDownloadOptimizedFlyer = () => {
    if (!flyerUpload) return;
    const link = document.createElement('a');
    link.href = flyerUpload.dataUrl;
    link.download = targetFilename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <fieldset className="tool-fieldset tool-fieldset-logistics">
      <legend className="tool-legend">2. Schedule, Venue &amp; Links</legend>

      <div className="tool-field-row-2">
        <div>
          <label htmlFor="ev-date" className="tool-label">
            Event Date &amp; Start Time (ISO) *
          </label>
          <span id="ev-date-hint" className="tool-hint">
            YYYY-MM-DDTHH:MM:SS-08:00 or YYYY-MM-DD
          </span>
          <input
            id="ev-date"
            name="eventDate"
            type="text"
            required
            className="tool-input"
            value={formData.eventDate}
            onChange={(e) => onChange({ eventDate: e.target.value })}
            placeholder="2026-11-12T16:00:00-08:00"
            autoCorrect="off"
            autoCapitalize="off"
            spellCheck={false}
            aria-describedby="ev-date-hint"
          />
          <div className="tool-error-msg">
            <span aria-hidden="true">❌</span> Enter the event date (e.g. 2026-11-12).
          </div>
          {normalizedIso && (
            <div className="tool-tz-preview">
              <div><strong>ISO:</strong> <code>{normalizedIso}</code></div>
              {tzCombinedLabel && <div><strong>Zones:</strong> {tzCombinedLabel}</div>}
            </div>
          )}
        </div>

        <div>
          <label htmlFor="ev-time-label" className="tool-label">
            Friendly Time Label
          </label>
          <span id="ev-timelabel-hint" className="tool-hint">
            Shown on card (e.g. 4:00 PM - 7:00 PM PST)
          </span>
          <input
            id="ev-time-label"
            name="timeLabel"
            type="text"
            className="tool-input"
            value={formData.timeLabel}
            onChange={(e) => onChange({ timeLabel: e.target.value })}
            placeholder="4:00 PM - 7:00 PM PST"
            aria-describedby="ev-timelabel-hint"
          />
        </div>
      </div>

      <div className="tool-field-group">
        <label htmlFor="ev-location" className="tool-label">
          Location / Physical Venue *
        </label>
        <span id="ev-location-hint" className="tool-hint">
          Full street address for in-person events, or &quot;Zoom Meeting&quot; for virtual sessions
        </span>
        <input
          id="ev-location"
          name="location"
          type="text"
          required
          className="tool-input"
          value={formData.location}
          onChange={(e) => onChange({ location: e.target.value })}
          placeholder="Chai N More, 12863 Northup Way Suite C, Bellevue, WA 98005"
          aria-describedby="ev-location-hint"
        />
        <div className="tool-error-msg">
          <span aria-hidden="true">❌</span> Please specify the venue address or &quot;Zoom Meeting&quot;.
        </div>
      </div>

      <div className="tool-field-group">
        <label htmlFor="ev-url" className="tool-label">
          Registration / RSVP Link (URL)
        </label>
        <span id="ev-url-hint" className="tool-hint">
          Full URL to Google Form, Zoom registration, or members.cegaana.org event page
        </span>
        <input
          id="ev-url"
          name="url"
          type="url"
          className="tool-input"
          value={formData.url}
          onChange={(e) => onChange({ url: e.target.value })}
          placeholder="https://forms.gle/... or https://us02web.zoom.us/meeting/register/..."
          autoCorrect="off"
          autoCapitalize="off"
          spellCheck={false}
          aria-describedby="ev-url-hint"
        />
      </div>

      <div className="tool-field-group">
        <label htmlFor="ev-maps-url" className="tool-label">
          Google Maps Link (Optional)
        </label>
        <span id="ev-maps-hint" className="tool-hint">
          Direct Google Maps navigation URL for physical venues
        </span>
        <input
          id="ev-maps-url"
          name="mapsUrl"
          type="url"
          className="tool-input"
          value={formData.mapsUrl}
          onChange={(e) => onChange({ mapsUrl: e.target.value })}
          placeholder="https://maps.app.goo.gl/..."
          autoCorrect="off"
          autoCapitalize="off"
          spellCheck={false}
          aria-describedby="ev-maps-hint"
        />
      </div>

      <div className="tool-field-group">
        <label htmlFor="ev-flyer-upload" className="tool-label">
          Event Flyer Image Upload (Optional)
        </label>
        <span id="ev-flyer-hint" className="tool-hint">
          JPG, PNG, or WebP (min 400×300 px; Portrait 4:5 / 2:3 or Landscape 16:9; auto-optimized under 500 KB)
        </span>
        <div className="tool-file-upload-box">
          <input
            ref={fileInputRef}
            id="ev-flyer-upload"
            name="flyerFile"
            type="file"
            accept="image/jpeg,image/png,image/webp"
            className="tool-file-input"
            onChange={handleFileChange}
            aria-describedby="ev-flyer-hint"
          />

          {flyerUpload && (
            <div className="tool-flyer-preview-card">
              <div className="tool-flyer-preview-left">
                <img
                  src={flyerUpload.dataUrl}
                  alt="Flyer preview"
                  className="tool-flyer-thumb"
                />
                <div className="tool-flyer-meta">
                  <div className="tool-flyer-filename">{targetAssetPath}</div>
                  <div className="tool-flyer-stats">
                    ✓ Optimized JPEG: {flyerUpload.width} × {flyerUpload.height} px ({Math.round(flyerUpload.sizeBytes / 1024)} KB)
                  </div>
                </div>
              </div>
              <div className="tool-flyer-actions">
                <button
                  type="button"
                  className="btn btn-outline btn-sm"
                  onClick={handleDownloadOptimizedFlyer}
                >
                  📥 Save .jpg
                </button>
                <button
                  type="button"
                  className="btn btn-outline btn-sm"
                  onClick={handleRemoveFlyer}
                >
                  ✕ Remove
                </button>
              </div>
            </div>
          )}

          {flyerError && (
            <div className="tool-status-banner tool-status-error" role="alert">
              ❌ {flyerError}
            </div>
          )}
        </div>
      </div>
    </fieldset>
  );
};
