import React, { useState } from 'react';
import type { WebsiteEvent } from '../../types/index.js';
import { formatEventDate } from '../../config/events.js';

export interface EventShareButtonProps {
  event: WebsiteEvent;
  className?: string;
}

export const EventShareButton: React.FC<EventShareButtonProps> = ({ event, className = '' }) => {
  const [copied, setCopied] = useState(false);

  const handleShare = async (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    const origin = typeof window !== 'undefined' ? window.location.origin : 'https://cegaana.org';
    const shareUrl = `${origin}/events/${event.slug}.html`;
    const dateLabel = event.timeLabel || formatEventDate(event.date);
    const shareText = `${event.title}${dateLabel ? ` — ${dateLabel}` : ''} | CEGAANA Alumni Event`;

    if (navigator.share) {
      try {
        await navigator.share({
          title: event.title,
          text: shareText,
          url: shareUrl,
        });
        return;
      } catch {
        // User dismissed native share sheet or unsupported, fallback to clipboard
      }
    }

    if (navigator.clipboard && window.isSecureContext) {
      try {
        await navigator.clipboard.writeText(`${shareText}\n${shareUrl}`);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
        return;
      } catch {
        // Fallback below
      }
    }

    const textArea = document.createElement('textarea');
    textArea.value = `${shareText}\n${shareUrl}`;
    textArea.style.position = 'fixed';
    textArea.style.opacity = '0';
    document.body.appendChild(textArea);
    textArea.select();
    try {
      document.execCommand('copy');
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } finally {
      document.body.removeChild(textArea);
    }
  };

  return (
    <button
      type="button"
      onClick={handleShare}
      className={`event-share-btn ${copied ? 'event-share-btn-copied' : ''} ${className}`}
      title={copied ? 'Link copied to clipboard!' : 'Share event link'}
      aria-label={`Share ${event.title}`}
    >
      <span>{copied ? '✓' : '🔗'}</span>
      <span>{copied ? 'Copied' : 'Share'}</span>
    </button>
  );
};
