/**
 * Operational Tools Configuration (@cegaana/website)
 * Configures write-only Google Forms and Google Apps Script Webhook endpoints
 * for the /p/tools/event-request utility so no recipient email is exposed in client code.
 */

const env = import.meta.env;

export interface EventRequestToolsConfig {
  /**
   * Public Google Form URL for write-only event submissions
   * Example: "https://docs.google.com/forms/d/e/1FAIpQLSe.../viewform"
   */
  googleFormUrl: string;
  /**
   * Google Apps Script Web App URL (doPost endpoint) that accepts write-only JSON payloads,
   * appends to Google Sheets / Form responses, and emails the formatted events.json payload.
   * Example: "https://script.google.com/macros/s/AKfycb.../exec"
   */
  appsScriptWebhookUrl: string;
}

export const toolsConfig: EventRequestToolsConfig = {
  googleFormUrl: (env.VITE_EVENT_REQUEST_GOOGLE_FORM_URL as string) || '',
  appsScriptWebhookUrl: (env.VITE_EVENT_REQUEST_WEBHOOK_URL as string) || ''
};

/**
 * Converts a standard Google Form view URL into an embeddable iframe URL.
 */
export function getEmbeddableGoogleFormUrl(formUrl: string): string {
  if (!formUrl) return '';
  try {
    const url = new URL(formUrl);
    url.searchParams.set('embedded', 'true');
    return url.toString();
  } catch {
    return formUrl.includes('?') ? `${formUrl}&embedded=true` : `${formUrl}?embedded=true`;
  }
}

