import React from 'react';

export type ContributionTheme = 'amber' | 'blue' | 'emerald' | 'purple';

interface ContributionMethodCardProps {
  icon: string;
  title: string;
  subtitle?: string;
  description: string;
  badgeLabel?: string;
  badgeValue?: string;
  badgeNote?: string;
  actionButton?: React.ReactNode;
  theme?: ContributionTheme;
}

const themeStyles: Record<ContributionTheme, {
  bg: string;
  topBar: string;
  border: string;
  titleColor: string;
  subtitleColor: string;
  badgeBg: string;
  badgeBorder: string;
}> = {
  amber: {
    bg: 'linear-gradient(145deg, #ffffff 0%, #fffbeb 50%, #fef3c7 100%)',
    topBar: 'linear-gradient(90deg, #d97706, #f59e0b)',
    border: 'rgba(217, 119, 6, 0.25)',
    titleColor: '#92400e',
    subtitleColor: '#b45309',
    badgeBg: 'rgba(255, 255, 255, 0.9)',
    badgeBorder: '#fde68a'
  },
  blue: {
    bg: 'linear-gradient(145deg, #ffffff 0%, #f0f7ff 50%, #e0f2fe 100%)',
    topBar: 'linear-gradient(90deg, #124E78, #0284c7)',
    border: 'rgba(18, 78, 120, 0.25)',
    titleColor: '#002D62',
    subtitleColor: '#0284c7',
    badgeBg: 'rgba(255, 255, 255, 0.9)',
    badgeBorder: '#cbd5e1'
  },
  emerald: {
    bg: 'linear-gradient(145deg, #ffffff 0%, #f0fdf4 50%, #dcfce7 100%)',
    topBar: 'linear-gradient(90deg, #059669, #10b981)',
    border: 'rgba(5, 150, 105, 0.25)',
    titleColor: '#065f46',
    subtitleColor: '#059669',
    badgeBg: 'rgba(255, 255, 255, 0.9)',
    badgeBorder: '#a7f3d0'
  },
  purple: {
    bg: 'linear-gradient(145deg, #ffffff 0%, #faf5ff 50%, #f3e8ff 100%)',
    topBar: 'linear-gradient(90deg, #7c3aed, #a855f7)',
    border: 'rgba(124, 58, 237, 0.25)',
    titleColor: '#5b21b6',
    subtitleColor: '#7c3aed',
    badgeBg: 'rgba(255, 255, 255, 0.9)',
    badgeBorder: '#ddd6fe'
  }
};

export const ContributionMethodCard: React.FC<ContributionMethodCardProps> = ({
  icon,
  title,
  subtitle,
  description,
  badgeLabel,
  badgeValue,
  badgeNote,
  actionButton,
  theme = 'blue'
}) => {
  const t = themeStyles[theme];

  return (
    <div
      className="card card-interactive"
      style={{
        position: 'relative',
        overflow: 'hidden',
        background: t.bg,
        border: `1px solid ${t.border}`,
        padding: '2rem',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'space-between',
        boxShadow: '0 4px 14px rgba(0, 0, 0, 0.04)'
      }}
    >
      <div
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          height: '4px',
          background: t.topBar
        }}
      />

      <div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '1rem' }}>
          <span style={{ fontSize: '2rem' }}>{icon}</span>
          <div>
            <h3 style={{ margin: 0, fontSize: '1.25rem', color: t.titleColor }}>
              {title}
            </h3>
            {subtitle && (
              <span style={{ fontSize: '0.8rem', color: t.subtitleColor, fontWeight: 600 }}>
                {subtitle}
              </span>
            )}
          </div>
        </div>

        <p style={{ fontSize: '0.925rem', lineHeight: 1.6, color: '#334155', marginBottom: '1.25rem' }}>
          {description}
        </p>

        {(badgeLabel || badgeValue) && (
          <div
            style={{
              backgroundColor: t.badgeBg,
              padding: '0.75rem 1rem',
              borderRadius: '8px',
              fontSize: '0.85rem',
              border: `1px solid ${t.badgeBorder}`,
              marginBottom: '1rem'
            }}
          >
            {badgeLabel && <span>{badgeLabel}: </span>}
            <strong>{badgeValue}</strong>
          </div>
        )}
      </div>

      <div>
        {badgeNote && (
          <div style={{ fontSize: '0.825rem', color: 'var(--color-text-muted)', lineHeight: 1.4, textAlign: 'center', padding: '0.5rem 0' }}>
            {badgeNote}
          </div>
        )}
        {actionButton && (
          <div style={{ marginTop: '0.5rem' }}>
            {actionButton}
          </div>
        )}
      </div>
    </div>
  );
};
