import React, { useState, useMemo } from 'react';
import type { PageProps } from './types.js';
import { Breadcrumb } from '../components/common/index.js';
import {
  EventIdentitySection,
  EventLogisticsSection,
  EventContentSection,
  EventProvenanceSection,
  EventJsonPreviewPanel,
  EventGoogleFormPanel
} from '../components/tools/index.js';
import { toolsConfig, getEmbeddableGoogleFormUrl } from '../config/tools.js';
import {
  INITIAL_EVENT_REQUEST_STATE,
  normalizeEventIsoDate,
  computeEventTimezonePreview,
  buildWebsiteEventJson,
  isEventRequestValid,
  processAndOptimizeFlyerImage,
  submitEventRequestToWebhook,
  type EventRequestFormState,
  type FlyerUploadData
} from '../utils/eventRequestBuilder.js';

export const EventRequestToolPage: React.FC<PageProps> = ({ onNavigate }) => {
  const [activeTab, setActiveTab] = useState<'builder' | 'google-form'>('builder');
  const [formData, setFormData] = useState<EventRequestFormState>(INITIAL_EVENT_REQUEST_STATE);
  const [flyerUpload, setFlyerUpload] = useState<FlyerUploadData | null>(null);
  const [flyerError, setFlyerError] = useState<string | null>(null);
  const [customWebhookUrl, setCustomWebhookUrl] = useState<string>(toolsConfig.appsScriptWebhookUrl);
  const [customGoogleFormUrl, setCustomGoogleFormUrl] = useState<string>(toolsConfig.googleFormUrl);
  const [submitting, setSubmitting] = useState<boolean>(false);
  const [statusMessage, setStatusMessage] = useState<{ type: 'success' | 'error' | 'info'; text: string } | null>(null);

  const updateFormFields = (updates: Partial<EventRequestFormState>) => {
    setFormData((prev) => ({ ...prev, ...updates }));
  };

  const eventJsonObj = useMemo(
    () => buildWebsiteEventJson(formData, Boolean(flyerUpload)),
    [formData, flyerUpload]
  );
  const eventJsonString = useMemo(() => JSON.stringify(eventJsonObj, null, 2), [eventJsonObj]);
  const normalizedIso = useMemo(
    () => normalizeEventIsoDate(formData.eventDate, formData.timeLabel),
    [formData.eventDate, formData.timeLabel]
  );
  const tzPreview = useMemo(
    () => computeEventTimezonePreview(normalizedIso),
    [normalizedIso]
  );
  const isFormValid = useMemo(() => isEventRequestValid(formData), [formData]);

  const handleFlyerSelect = async (file: File | null) => {
    setFlyerError(null);
    if (!file) {
      setFlyerUpload(null);
      return;
    }

    try {
      const slugOrTitle = formData.slug.trim() || formData.title.trim() || 'new-cegaana-event';
      const processed = await processAndOptimizeFlyerImage(file, slugOrTitle);
      setFlyerUpload(processed);
    } catch (err) {
      setFlyerUpload(null);
      setFlyerError(err instanceof Error ? err.message : String(err));
    }
  };

  const handleCopyJson = async () => {
    try {
      await navigator.clipboard.writeText(eventJsonString);
      setStatusMessage({
        type: 'success',
        text: '✓ Copied formatted Event JSON to clipboard!'
      });
    } catch (err) {
      setStatusMessage({
        type: 'error',
        text: `Clipboard copy failed: ${err instanceof Error ? err.message : String(err)}`
      });
    }
  };

  const handleDownloadJson = () => {
    const slug = String(eventJsonObj.slug || 'cegaana-event');
    const blob = new Blob([`${eventJsonString}\n`], { type: 'application/json;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${slug}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
    setStatusMessage({
      type: 'info',
      text: `📥 Downloaded ${slug}.json`
    });
  };

  const handleReset = () => {
    setFormData(INITIAL_EVENT_REQUEST_STATE);
    setFlyerUpload(null);
    setFlyerError(null);
    setStatusMessage(null);
  };

  const handleSubmitWebhook = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!isFormValid) return;

    const targetWebhook = customWebhookUrl.trim();
    if (!targetWebhook) {
      setStatusMessage({
        type: 'info',
        text: 'No Google Apps Script Webhook URL configured yet. Copy the Event JSON on the right, or configure VITE_EVENT_REQUEST_WEBHOOK_URL to enable 1-click write-only dispatch.'
      });
      return;
    }

    setSubmitting(true);
    setStatusMessage(null);
    try {
      const result = await submitEventRequestToWebhook(
        targetWebhook,
        formData,
        eventJsonObj,
        flyerUpload
      );
      setStatusMessage({
        type: result.ok ? 'success' : 'error',
        text: `✓ ${result.message}`
      });
    } catch (err) {
      setStatusMessage({
        type: 'error',
        text: `Webhook dispatch failed: ${err instanceof Error ? err.message : String(err)}`
      });
    } finally {
      setSubmitting(false);
    }
  };

  const embedUrl = getEmbeddableGoogleFormUrl(customGoogleFormUrl.trim());

  return (
    <div>
      <header className="tool-topbar">
        <div className="container tool-topbar-inner">
          <div className="tool-topbar-left">
            <h1 className="tool-topbar-title">📅 New Event Request &amp; JSON Generator</h1>
            <p className="tool-topbar-subtitle">
              Author structured event details, generate events.json, and submit via webhook.
            </p>
          </div>
          <button
            type="button"
            className="btn btn-hero-outline btn-sm"
            onClick={(e) => onNavigate('/p/tools', e)}
          >
            ← All Tools
          </button>
        </div>
      </header>

      <section className="section-sm section-muted">
        <div className="container">
          <Breadcrumb
            items={[
              { label: 'Home', path: '/' },
              { label: 'Operational Tools', path: '/p/tools' },
              { label: 'New Event Request' }
            ]}
            onNavigate={onNavigate}
          />

          <div className="tool-tabs" role="tablist" aria-label="Event Request Workflow Tabs">
            <button
              type="button"
              role="tab"
              aria-selected={activeTab === 'builder'}
              className={`tool-tab-btn ${activeTab === 'builder' ? 'tool-tab-btn-active' : ''}`}
              onClick={() => setActiveTab('builder')}
            >
              🛠️ Interactive Event JSON Builder
            </button>
            <button
              type="button"
              role="tab"
              aria-selected={activeTab === 'google-form'}
              className={`tool-tab-btn ${activeTab === 'google-form' ? 'tool-tab-btn-active' : ''}`}
              onClick={() => setActiveTab('google-form')}
            >
              📋 Write-Only Google Form
            </button>
          </div>

          {activeTab === 'builder' && (
            <div className="tool-workspace-grid">
              <div className="tool-panel">
                <h2 className="tool-panel-title">Event Request Fields</h2>
                <p className="tool-panel-subtitle">
                  Mirrors all fields from the CEGAANA Admin Portal Events Creator. Required fields are marked with *.
                </p>

                <form onSubmit={handleSubmitWebhook}>
                  <EventIdentitySection
                    formData={formData}
                    computedSlug={String(eventJsonObj.slug || '')}
                    onChange={updateFormFields}
                  />

                  <EventLogisticsSection
                    formData={formData}
                    computedSlug={String(eventJsonObj.slug || '')}
                    normalizedIso={normalizedIso}
                    tzCombinedLabel={tzPreview?.combined}
                    flyerUpload={flyerUpload}
                    flyerError={flyerError}
                    onChange={updateFormFields}
                    onFlyerSelect={handleFlyerSelect}
                  />

                  <EventContentSection
                    formData={formData}
                    onChange={updateFormFields}
                  />

                  <EventProvenanceSection
                    formData={formData}
                    showCustomWebhookInput={!toolsConfig.appsScriptWebhookUrl}
                    customWebhookUrl={customWebhookUrl}
                    onChange={updateFormFields}
                    onWebhookUrlChange={setCustomWebhookUrl}
                  />

                  <div className="tool-submit-bar">
                    <button
                      type="submit"
                      disabled={!isFormValid || submitting}
                      className="btn btn-primary btn-full btn-lg"
                    >
                      {submitting
                        ? 'Submitting Event Request...'
                        : '🚀 Submit Event Request via Webhook (Write-Only)'}
                    </button>
                    {!isFormValid && (
                      <span className="tool-submit-note">
                        Complete all required fields (*) above to enable webhook submission.
                      </span>
                    )}
                  </div>
                </form>
              </div>

              <EventJsonPreviewPanel
                eventJsonString={eventJsonString}
                statusMessage={statusMessage}
                onCopyJson={handleCopyJson}
                onDownloadJson={handleDownloadJson}
                onReset={handleReset}
              />
            </div>
          )}

          {activeTab === 'google-form' && (
            <EventGoogleFormPanel
              customGoogleFormUrl={customGoogleFormUrl}
              embedUrl={embedUrl}
              showUrlInput={!toolsConfig.googleFormUrl}
              onGoogleFormUrlChange={setCustomGoogleFormUrl}
            />
          )}
        </div>
      </section>
    </div>
  );
};
