import React from 'react';
import type { EventLifecycleStatus } from '../../types/index.js';
import { Badge } from '../common/Badge.js';

interface EventStatusBadgeProps {
  status: EventLifecycleStatus;
}

export const EventStatusBadge: React.FC<EventStatusBadgeProps> = ({ status }) => {
  switch (status) {
    case 'completed':
      return <Badge variant="completed">✓ Concluded</Badge>;
    case 'active':
      return <Badge variant="success">● Registration Open</Badge>;
    case 'upcoming':
      return <Badge variant="warning">⏱ Upcoming</Badge>;
    case 'archived':
      return <Badge variant="completed">Archived</Badge>;
    default:
      return null;
  }
};
