import React from 'react';
import { Badge } from '../common/index.js';

export interface EventJsonPreviewPanelProps {
  eventJsonString: string;
  statusMessage: { type: 'success' | 'error' | 'info'; text: string } | null;
  onCopyJson: () => void;
  onDownloadJson: () => void;
  onReset: () => void;
}

export const EventJsonPreviewPanel: React.FC<EventJsonPreviewPanelProps> = ({
  eventJsonString,
  statusMessage,
  onCopyJson,
  onDownloadJson,
  onReset
}) => {
  return (
    <div className="tool-panel tool-panel-sticky">
      <div className="flex-between">
        <h2 className="tool-panel-title">Generated Event JSON</h2>
        <Badge variant="secondary">events.json</Badge>
      </div>
      <p className="tool-panel-subtitle">
        Ready to paste into <code>tools/website/src/data/events.json</code> or Admin Portal Cut &amp; Paste modal.
      </p>

      <pre className="tool-code-box">
        <code>{eventJsonString}</code>
      </pre>

      <button
        type="button"
        className="btn btn-primary btn-full btn-lg"
        onClick={onCopyJson}
      >
        📋 Copy Event JSON to Clipboard
      </button>

      <div className="tool-actions-grid">
        <button
          type="button"
          className="btn btn-secondary btn-sm"
          onClick={onDownloadJson}
        >
          📥 Download .json File
        </button>
        <button
          type="button"
          className="btn btn-outline btn-sm"
          onClick={onReset}
        >
          🔄 Reset Form Fields
        </button>
      </div>

      {statusMessage && (
        <div
          className={`tool-status-banner tool-status-${statusMessage.type}`}
          role="status"
          aria-live="polite"
        >
          {statusMessage.text}
        </div>
      )}
    </div>
  );
};

