const DEFAULT_QR_OPTIONS: Required<QROptions> = {
  errorCorrectionLevel: 'M',
  margin: 4,
  width: 660,
  darkColor: '#000000',
  lightColor: '#ffffff'
};

function escapeXml(unsafe: string): string {
  return unsafe
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

/**
 * Generates a clean vector SVG string for the given text/URL.
 */
export async function generateQrSvg(text: string, options: QROptions = {}): Promise<string> {
  const opts = { ...DEFAULT_QR_OPTIONS, ...options };
  return QRCode.toString(text || 'https://cegaana.org', {
    type: 'svg',
    errorCorrectionLevel: opts.errorCorrectionLevel,
    margin: opts.margin,
    width: opts.width,
    color: {
      dark: opts.darkColor,
      light: opts.lightColor
    }
  });
}

/**
 * Encodes an SVG string into a browser-compatible Data URI.
 */
export function svgToDataUri(svg: string): string {
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
}

/**
 * Generates an SVG Data URI for injecting directly into <img> tags.
 */
export async function generateQrDataUri(text: string, options: QROptions = {}): Promise<string> {
  const svg = await generateQrSvg(text, options);
  return svgToDataUri(svg);
}

/**
 * Generates a standardized 880 × 1055 px branded CEGAANA QR card vector SVG
 * adhering to tools/scripts/generate-qr-code.py.
 */
export async function generateBrandedQrCardSvg(
  url: string,
  options: BrandedQrCardOptions
): Promise<string> {
  const outerBg = options.outerBg || '#2b7431';
  const badgeBg = options.badgeBg || '#ffd978';
  const badgeTextColor = options.badgeTextColor || '#215926';
  const fontSize = options.fontSize || 50;
  const label = escapeXml(options.label || 'CEGAANA');

  const innerQrSvg = await generateQrSvg(url || 'https://cegaana.org', {
    errorCorrectionLevel: options.errorCorrectionLevel || 'M',
    margin: 0,
    width: 660,
    darkColor: options.darkColor || '#000000',
    lightColor: options.lightColor || '#ffffff'
  });

  const positionedQrSvg = innerQrSvg
    .trim()
    .replace('<svg ', '<svg x="110" y="110" ');

  return `<svg width="880" height="1055" viewBox="0 0 880 1055" xmlns="http://www.w3.org/2000/svg">
  <!-- Outer card with 40px radius -->
  <rect x="0" y="0" width="880" height="1055" rx="40" ry="40" fill="${escapeXml(outerBg)}" />
  <!-- White QR panel with 30px radius -->
  <rect x="60.5" y="60" width="759" height="759" rx="30" ry="30" fill="#ffffff" />
  <!-- Centered 660x660 QR Code Matrix -->
  ${positionedQrSvg}
  <!-- Badge panel with 20px radius and dashed border -->
  <rect x="60.5" y="850" width="759" height="144" rx="20" ry="20" fill="${escapeXml(badgeBg)}" stroke="#000000" stroke-width="3" stroke-dasharray="11 6" />
  <!-- Centered Badge Label -->
  <text x="440" y="935" font-family="Arial, Helvetica, sans-serif" font-size="${fontSize}" font-weight="bold" fill="${escapeXml(badgeTextColor)}" text-anchor="middle">${label}</text>
</svg>`;
}

/**
 * Rasterizes an SVG string onto an offscreen HTML5 Canvas at exact pixel dimensions.
 */
export function renderSvgToCanvas(
  svgString: string,
  width: number,
  height: number
): Promise<HTMLCanvasElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        reject(new Error('Could not initialize 2D canvas context'));
        return;
      }
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, width, height);
      ctx.drawImage(img, 0, 0, width, height);
      resolve(canvas);
    };
    img.onerror = () => reject(new Error('Failed to load SVG into image element'));
    img.src = svgToDataUri(svgString);
  });
}

/**
 * Copies the rendered QR image (PNG blob) directly to the user's system clipboard.
 */
export async function copySvgAsPngToClipboard(
  svgString: string,
  width: number,
  height: number
): Promise<void> {
  const canvas = await renderSvgToCanvas(svgString, width, height);
  const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/png'));
  if (!blob) {
    throw new Error('Failed to encode PNG blob for clipboard');
  }
  await navigator.clipboard.write([
    new ClipboardItem({
      'image/png': blob
    })
  ]);
}

/**
 * Downloads the QR asset as JPEG (quality=0.95), PNG, or vector SVG.
 */
export async function downloadQrAsset(
  svgString: string,
  filenameBase: string,
  format: 'jpeg' | 'png' | 'svg',
  width: number,
  height: number
): Promise<void> {
  const safeBase = filenameBase.replace(/[^a-zA-Z0-9_-]+/g, '-').replace(/^-+|-+$/g, '') || 'CEGAANA-QRCode';

  if (format === 'svg') {
    const blob = new Blob([svgString], { type: 'image/svg+xml;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    triggerBrowserDownload(url, `${safeBase}.svg`);
    URL.revokeObjectURL(url);
    return;
  }

  const canvas = await renderSvgToCanvas(svgString, width, height);
  const mimeType = format === 'jpeg' ? 'image/jpeg' : 'image/png';
  const ext = format === 'jpeg' ? 'jpg' : 'png';
  const dataUrl = canvas.toDataURL(mimeType, format === 'jpeg' ? 0.95 : undefined);
  triggerBrowserDownload(dataUrl, `${safeBase}.${ext}`);
}

function triggerBrowserDownload(href: string, filename: string): void {
  const link = document.createElement('a');
  link.href = href;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
}

