import React from 'react';
import type { EventRequestFormState } from '../../utils/eventRequestBuilder.js';

export interface EventProvenanceSectionProps {
  formData: EventRequestFormState;
  showCustomWebhookInput: boolean;
  customWebhookUrl: string;
  onChange: (updates: Partial<EventRequestFormState>) => void;
  onWebhookUrlChange: (url: string) => void;
}

export const EventProvenanceSection: React.FC<EventProvenanceSectionProps> = ({
  formData,
  showCustomWebhookInput,
  customWebhookUrl,
  onChange,
  onWebhookUrlChange
}) => {
  return (
    <fieldset className="tool-fieldset tool-fieldset-provenance">
      <legend className="tool-legend">4. Submitter Provenance &amp; Notes</legend>

      <div className="tool-field-group">
        <label htmlFor="ev-submitted-by" className="tool-label">
          Submitted By (Name, Grad Year &amp; Contact) *
        </label>
        <span id="ev-submitted-by-hint" className="tool-hint">
          Coordinator or host submitting this event request
        </span>
        <input
          id="ev-submitted-by"
          name="submittedBy"
          type="text"
          required
          className="tool-input"
          value={formData.submittedBy}
          onChange={(e) => onChange({ submittedBy: e.target.value })}
          placeholder="e.g. John (2006 ECE)"
          aria-describedby="ev-submitted-by-hint"
        />
        <div className="tool-error-msg">
          <span aria-hidden="true">❌</span> Please enter your name and batch year (e.g. John (2006 ECE)).
        </div>
      </div>

      <div className="tool-field-group">
        <label htmlFor="ev-comments" className="tool-label">
          Organizer Notes / Logistics (Optional)
        </label>
        <span id="ev-comments-hint" className="tool-hint">
          Special instructions, logistics, or publishing notes for operations
        </span>
        <textarea
          id="ev-comments"
          name="comments"
          rows={2}
          className="tool-textarea"
          value={formData.comments}
          onChange={(e) => onChange({ comments: e.target.value })}
          placeholder="Any special publishing notes, parking details, or logistics..."
          aria-describedby="ev-comments-hint"
        />
      </div>

      {showCustomWebhookInput && (
        <div className="tool-field-group">
          <label htmlFor="ev-webhook-url" className="tool-label">
            Google Apps Script Webhook URL (Write-Only Endpoint)
          </label>
          <span id="ev-webhook-hint" className="tool-hint">
            Set <code>VITE_EVENT_REQUEST_WEBHOOK_URL</code> in <code>.env</code> or paste your Web App URL below
          </span>
          <input
            id="ev-webhook-url"
            name="webhookUrl"
            type="url"
            className="tool-input"
            value={customWebhookUrl}
            onChange={(e) => onWebhookUrlChange(e.target.value)}
            placeholder="https://script.google.com/macros/s/.../exec"
            autoCorrect="off"
            autoCapitalize="off"
            spellCheck={false}
            aria-describedby="ev-webhook-hint"
          />
        </div>
      )}
    </fieldset>
  );
};

