import React, { useState, useEffect } from 'react';
import { BaseLayout } from './components/layout/BaseLayout.js';
import { resolveRoute } from './routes/index.js';
import { updatePageSeo } from './utils/seo.js';
import { NotFoundPage } from './pages/NotFoundPage.js';

export const App: React.FC = () => {
  const [currentPath, setCurrentPath] = useState(window.location.pathname);

  useEffect(() => {
    const handlePopState = () => setCurrentPath(window.location.pathname);
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  const navigate = (path: string, e?: React.MouseEvent) => {
    if (e) e.preventDefault();
    window.history.pushState({}, '', path);
    setCurrentPath(path);
    window.scrollTo(0, 0);
  };

  const currentRoute = resolveRoute(currentPath);

  useEffect(() => {
    updatePageSeo(currentRoute, currentPath);
  }, [currentRoute, currentPath]);

  const CurrentPageComponent = currentRoute ? currentRoute.component : NotFoundPage;

  return (
    <BaseLayout onNavigate={navigate}>
      <CurrentPageComponent onNavigate={navigate} />
    </BaseLayout>
  );
};

