import type { WebsiteEvent } from '../types/index.js';

/**
 * Generates RFC 5545 compliant iCalendar (.ics) format string for an event.
 */
export function generateEventIcs(event: WebsiteEvent): string {
  const startDate = new Date(event.date);
  // Default event duration: 1 hour (60 minutes) if not specified
  const endDate = new Date(startDate.getTime() + 60 * 60 * 1000);

  const formatIcsDate = (d: Date): string => {
    return d.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
  };

  const dtStart = isNaN(startDate.getTime())
    ? formatIcsDate(new Date())
    : formatIcsDate(startDate);
  const dtEnd = isNaN(endDate.getTime())
    ? formatIcsDate(new Date(Date.now() + 3600000))
    : formatIcsDate(endDate);
  const dtStamp = formatIcsDate(new Date());
  const uid = `${event.slug || event.id}-${dtStart}@cegaana.org`;

  // Clean HTML tags and escape special iCalendar characters
  const cleanDescription = (event.description || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/[,;\\]/g, (match) => `\\${match}`);

  const cleanTitle = (event.title || '')
    .trim()
    .replace(/[,;\\]/g, (match) => `\\${match}`);

  const cleanLocation = (event.location || 'Online / Zoom')
    .trim()
    .replace(/[,;\\]/g, (match) => `\\${match}`);

  const icsLines = [
    'BEGIN:VCALENDAR',
    'VERSION:2.0',
    'PRODID:-//CEGAANA//Alumni Events Calendar//EN',
    'CALSCALE:GREGORIAN',
    'METHOD:PUBLISH',
    'BEGIN:VEVENT',
    `UID:${uid}`,
    `DTSTAMP:${dtStamp}`,
    `DTSTART:${dtStart}`,
    `DTEND:${dtEnd}`,
    `SUMMARY:${cleanTitle}`,
    `DESCRIPTION:${cleanDescription}`,
    `LOCATION:${cleanLocation}`,
  ];

  if (event.url) {
    icsLines.push(`URL:${event.url}`);
  }

  icsLines.push('STATUS:CONFIRMED');
  icsLines.push('END:VEVENT');
  icsLines.push('END:VCALENDAR');

  return icsLines.join('\r\n');
}

/**
 * Triggers a browser file download of the event's .ics calendar file.
 */
export function downloadEventIcs(event: WebsiteEvent): void {
  const icsContent = generateEventIcs(event);
  const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
  const downloadUrl = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = downloadUrl;
  anchor.setAttribute('download', `${event.slug || `event-${event.id}`}.ics`);
  document.body.appendChild(anchor);
  anchor.click();
  document.body.removeChild(anchor);
  URL.revokeObjectURL(downloadUrl);
}
