/**
 * CEGAANA New Event Request & Event JSON Builder
 * Mirrors the schema and normalization rules from tools/admin/src/components/events/EventFormModal.tsx
 * and @cegaana/shared events service, producing ready-to-commit WebsiteEvent JSON objects.
 */

export interface EventRequestFormState {
  title: string;
  slug: string;
  category: 'meet' | 'panel' | 'outdoor' | 'webinar' | 'social' | 'conference';
  status: 'active' | 'upcoming' | 'completed' | 'archived';
  eventDate: string;
  timeLabel: string;
  expiresAt: string;
  location: string;
  url: string;
  mapsUrl: string;
  imageUrl: string;
  tagsText: string;
  description: string;
  socialDescription: string;
  zoomJoinUrl: string;
  zoomMeetingId: string;
  zoomPasscode: string;
  speakersText: string;
  submittedBy: string;
  comments: string;
}

export interface FlyerUploadData {
  filename: string;
  mimeType: string;
  base64: string;
  dataUrl: string;
  width: number;
  height: number;
  sizeBytes: number;
  originalSizeBytes: number;
}

export const FLYER_IMAGE_CONSTRAINTS = {
  maxInputBytes: 5 * 1024 * 1024, // 5 MB raw file limit
  maxOutputBytes: 500 * 1024,    // 500 KB optimized output cap
  minWidth: 400,
  minHeight: 300,
  maxWidth: 1200,
  maxHeight: 1600,
  minAspectRatio: 0.45,          // Reject overly tall thin strips (e.g. < 9:20)
  maxAspectRatio: 3.0            // Reject overly wide banners (e.g. > 3:1)
} as const;

export const INITIAL_EVENT_REQUEST_STATE: EventRequestFormState = {
  title: '',
  slug: '',
  category: 'meet',
  status: 'active',
  eventDate: '',
  timeLabel: '',
  expiresAt: '',
  location: '',
  url: '',
  mapsUrl: '',
  imageUrl: '',
  tagsText: '',
  description: '',
  socialDescription: '',
  zoomJoinUrl: '',
  zoomMeetingId: '',
  zoomPasscode: '',
  speakersText: '',
  submittedBy: '',
  comments: ''
};

export function slugifyEventTitle(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .trim()
    .replace(/[\s_-]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

/**
 * Computes the canonical flyer filename (<slug>-flyer.jpg) and public asset path.
 */
export function getCanonicalFlyerPaths(titleOrSlug: string): {
  filename: string;
  assetPath: string;
} {
  const cleanSlug = slugifyEventTitle(titleOrSlug || 'new-cegaana-event') || 'new-cegaana-event';
  const filename = `${cleanSlug}-flyer.jpg`;
  return {
    filename,
    assetPath: `/assets/events/${filename}`
  };
}

/**
 * Validates image file type, raw file size, dimensions, and aspect ratio,
 * then downscales and compresses to a standardized JPEG under 500 KB.
 */
export async function processAndOptimizeFlyerImage(
  file: File,
  slugOrTitle: string
): Promise<FlyerUploadData> {
  const allowedTypes = ['image/jpeg', 'image/png', 'image/webp'];
  if (!allowedTypes.includes(file.type)) {
    throw new Error('Unsupported format. Please upload a JPG, PNG, or WebP image.');
  }

  if (file.size > FLYER_IMAGE_CONSTRAINTS.maxInputBytes) {
    const sizeMb = (file.size / (1024 * 1024)).toFixed(1);
    throw new Error(`Image is too large (${sizeMb} MB). Maximum raw file size is 5 MB.`);
  }

  const rawDataUrl = await new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ''));
    reader.onerror = () => reject(new Error('Could not read selected image file.'));
    reader.readAsDataURL(file);
  });

  const img = await new Promise<HTMLImageElement>((resolve, reject) => {
    const element = new Image();
    element.onload = () => resolve(element);
    element.onerror = () => reject(new Error('Invalid or corrupted image file.'));
    element.src = rawDataUrl;
  });

  const srcWidth = img.naturalWidth || img.width;
  const srcHeight = img.naturalHeight || img.height;

  if (srcWidth < FLYER_IMAGE_CONSTRAINTS.minWidth || srcHeight < FLYER_IMAGE_CONSTRAINTS.minHeight) {
    throw new Error(
      `Image dimensions (${srcWidth} × ${srcHeight} px) are too small. Minimum required is ${FLYER_IMAGE_CONSTRAINTS.minWidth} × ${FLYER_IMAGE_CONSTRAINTS.minHeight} px.`
    );
  }

  const aspect = srcWidth / srcHeight;
  if (aspect < FLYER_IMAGE_CONSTRAINTS.minAspectRatio || aspect > FLYER_IMAGE_CONSTRAINTS.maxAspectRatio) {
    throw new Error(
      `Inappropriate aspect ratio (${srcWidth} × ${srcHeight} px). Use standard Portrait (4:5 or 2:3, e.g. 1080 × 1350 px) or Landscape (16:9, e.g. 1200 × 630 px).`
    );
  }

  // Scale down proportionally if larger than 1200 × 1600 px
  const scale = Math.min(
    1,
    FLYER_IMAGE_CONSTRAINTS.maxWidth / srcWidth,
    FLYER_IMAGE_CONSTRAINTS.maxHeight / srcHeight
  );
  const targetWidth = Math.round(srcWidth * scale);
  const targetHeight = Math.round(srcHeight * scale);

  const canvas = document.createElement('canvas');
  canvas.width = targetWidth;
  canvas.height = targetHeight;
  const ctx = canvas.getContext('2d');
  if (!ctx) {
    throw new Error('Could not initialize image compression canvas.');
  }

  // Fill white background for transparent PNGs before encoding to JPEG
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, targetWidth, targetHeight);
  ctx.drawImage(img, 0, 0, targetWidth, targetHeight);

  // Encode JPEG and step down quality if needed to guarantee < 500 KB
  let quality = 0.86;
  let optimizedDataUrl = canvas.toDataURL('image/jpeg', quality);
  let base64 = optimizedDataUrl.split(',')[1] || '';
  let sizeBytes = Math.round((base64.length * 3) / 4);

  while (sizeBytes > FLYER_IMAGE_CONSTRAINTS.maxOutputBytes && quality > 0.55) {
    quality -= 0.08;
    optimizedDataUrl = canvas.toDataURL('image/jpeg', quality);
    base64 = optimizedDataUrl.split(',')[1] || '';
    sizeBytes = Math.round((base64.length * 3) / 4);
  }

  if (sizeBytes > FLYER_IMAGE_CONSTRAINTS.maxOutputBytes) {
    throw new Error('Compressed image still exceeds 500 KB. Please choose a simpler flyer graphic.');
  }

  const { filename } = getCanonicalFlyerPaths(slugOrTitle);

  return {
    filename,
    mimeType: 'image/jpeg',
    base64,
    dataUrl: optimizedDataUrl,
    width: targetWidth,
    height: targetHeight,
    sizeBytes,
    originalSizeBytes: file.size
  };
}

/**
 * Checks whether all required fields in the Event Request form are filled.
 */
export function isEventRequestValid(formData: EventRequestFormState): boolean {
  return (
    formData.title.trim().length >= 3 &&
    formData.eventDate.trim().length > 0 &&
    formData.location.trim().length > 0 &&
    formData.description.trim().length > 0 &&
    formData.submittedBy.trim().length > 0
  );
}

/**
 * Normalizes a plain date or date+time string into a full ISO 8601 timestamp with Pacific Time offset.
 */
export function normalizeEventIsoDate(rawDate?: string, timeLabel?: string): string {
  if (!rawDate) return '';
  const trimmed = rawDate.trim();
  if (!trimmed) return '';

  if (trimmed.includes('Z') || /[+-]\d{2}(:?\d{2})?$/.test(trimmed)) {
    return trimmed;
  }

  let ymd = trimmed;
  let timePart = '';

  if (trimmed.includes('T')) {
    const [d, t] = trimmed.split('T');
    ymd = d;
    timePart = t;
  }

  if (!/^\d{4}-\d{2}-\d{2}$/.test(ymd)) {
    return trimmed;
  }

  if (!timePart && timeLabel) {
    const timeMatch = timeLabel.match(/(\d{1,2})(?::(\d{2}))?\s*(am|pm)?/i);
    if (timeMatch) {
      let hour = parseInt(timeMatch[1], 10);
      const minute = timeMatch[2] ? parseInt(timeMatch[2], 10) : 0;
      const ampm = timeMatch[3]?.toLowerCase();

      if (ampm === 'pm' && hour < 12) hour += 12;
      if (ampm === 'am' && hour === 12) hour = 0;

      const pad = (n: number) => String(n).padStart(2, '0');
      timePart = `${pad(hour)}:${pad(minute)}:00`;
    }
  }

  if (!timePart) {
    timePart = '12:00:00';
  } else if (timePart.length === 5) {
    timePart += ':00';
  }

  let offset = '-08:00';
  try {
    const testDate = new Date(`${ymd}T${timePart}Z`);
    if (!isNaN(testDate.getTime())) {
      const formatter = new Intl.DateTimeFormat('en-US', {
        timeZone: 'America/Los_Angeles',
        timeZoneName: 'longOffset'
      });
      const parts = formatter.formatToParts(testDate);
      const tzPart = parts.find(p => p.type === 'timeZoneName');
      if (tzPart && tzPart.value.startsWith('GMT')) {
        offset = tzPart.value.replace('GMT', '');
      }
    }
  } catch {
    offset = '-08:00';
  }

  return `${ymd}T${timePart}${offset}`;
}

/**
 * Computes PST, EST, and IST formatted start times for an ISO date string.
 */
export function computeEventTimezonePreview(dateIso: string): {
  pst: string;
  est: string;
  ist: string;
  combined: string;
} | null {
  if (!dateIso) return null;
  const normalized = normalizeEventIsoDate(dateIso);
  const d = new Date(normalized);
  if (isNaN(d.getTime())) return null;

  try {
    const pst = new Intl.DateTimeFormat('en-US', {
      timeZone: 'America/Los_Angeles',
      hour: 'numeric',
      minute: '2-digit',
      timeZoneName: 'short'
    }).format(d);

    const est = new Intl.DateTimeFormat('en-US', {
      timeZone: 'America/New_York',
      hour: 'numeric',
      minute: '2-digit',
      timeZoneName: 'short'
    }).format(d);

    const istTime = new Intl.DateTimeFormat('en-US', {
      timeZone: 'Asia/Kolkata',
      hour: 'numeric',
      minute: '2-digit'
    }).format(d);

    const ist = `${istTime} IST`;
    return {
      pst,
      est,
      ist,
      combined: `${pst} / ${est} / ${ist}`
    };
  } catch {
    return null;
  }
}

/**
 * Builds the canonical WebsiteEvent JSON record matching tools/website/src/data/events.json.
 */
export function buildWebsiteEventJson(
  formData: EventRequestFormState,
  hasFlyerUpload: boolean = false
): Record<string, unknown> {
  const slug = formData.slug.trim() || slugifyEventTitle(formData.title || 'new-cegaana-event');
  const normalizedDate = normalizeEventIsoDate(formData.eventDate, formData.timeLabel);
  const tzPreview = computeEventTimezonePreview(normalizedDate);

  const panelists = formData.speakersText
    .split('\n')
    .map(line => line.trim())
    .filter(Boolean)
    .map(line => {
      const parts = line.split('|').map(p => p.trim());
      const entry: Record<string, string> = { name: parts[0] };
      if (parts[1]) entry.url = parts[1];
      if (parts[2]) entry.role = parts[2];
      return entry;
    });

  const tags = formData.tagsText
    .split(',')
    .map(t => t.trim())
    .filter(Boolean);

  const resolvedImagePath = hasFlyerUpload
    ? getCanonicalFlyerPaths(slug).assetPath
    : (formData.imageUrl.trim() || undefined);

  const eventObj: Record<string, unknown> = {
    slug,
    title: formData.title.trim() || 'Untitled Event',
    category: formData.category,
    date: normalizedDate || formData.eventDate.trim(),
    timeLabel: formData.timeLabel.trim() || tzPreview?.pst || undefined,
    location: formData.location.trim() || 'Zoom / Virtual',
    description: formData.description.trim() || undefined,
    socialDescription: formData.socialDescription.trim() || undefined,
    image: resolvedImagePath,
    flyerUrl: resolvedImagePath,
    url: formData.url.trim() || undefined,
    maps_url: formData.mapsUrl.trim() || undefined,
    status: formData.status
  };

  if (formData.zoomJoinUrl.trim()) eventObj.url_meet = formData.zoomJoinUrl.trim();
  if (formData.zoomMeetingId.trim()) eventObj.zoom_meeting_id = formData.zoomMeetingId.trim();
  if (formData.zoomPasscode.trim()) eventObj.zoom_passcode = formData.zoomPasscode.trim();
  if (panelists.length > 0) eventObj.panelists = panelists;
  if (tags.length > 0) eventObj.tags = tags;
  if (formData.expiresAt.trim()) eventObj.expires_at = formData.expiresAt.trim();
  if (formData.submittedBy.trim()) eventObj.submitted_by = formData.submittedBy.trim();
  if (formData.comments.trim()) eventObj.comments = formData.comments.trim();

  // Remove undefined keys for clean JSON output
  return Object.fromEntries(
    Object.entries(eventObj).filter(([, value]) => value !== undefined && value !== '')
  );
}

/**
 * Posts the event request payload (plus optional compressed flyer image) to a Google Apps Script Web App endpoint.
 */
export async function submitEventRequestToWebhook(
  webhookUrl: string,
  formState: EventRequestFormState,
  eventJson: Record<string, unknown>,
  flyerUpload?: FlyerUploadData | null
): Promise<{ ok: boolean; message: string }> {
  const slug = String(eventJson.slug || 'new-cegaana-event');
  const { filename } = getCanonicalFlyerPaths(slug);

  const payload = {
    source: 'cegaana-website-tools',
    submittedAt: new Date().toISOString(),
    formFields: formState,
    eventJson,
    flyerUpload: flyerUpload
      ? {
          filename,
          mimeType: flyerUpload.mimeType,
          base64: flyerUpload.base64,
          width: flyerUpload.width,
          height: flyerUpload.height,
          sizeBytes: flyerUpload.sizeBytes
        }
      : undefined
  };

  const response = await fetch(webhookUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'text/plain;charset=utf-8'
    },
    body: JSON.stringify(payload)
  });

  if (!response.ok) {
    throw new Error(`Webhook returned HTTP ${response.status}`);
  }

  try {
    const result = (await response.json()) as { ok?: boolean; message?: string };
    return {
      ok: result.ok !== false,
      message: result.message || 'Event request submitted and emailed for review.'
    };
  } catch {
    return {
      ok: true,
      message: 'Event request submitted successfully.'
    };
  }
}
