/**
 * Feature Flags Configuration for @cegaana/website
 * Controls conditional visibility, access gating, and migration stages.
 */

const env = import.meta.env;

export interface FeatureFlags {
  // Future Event Templates (e.g. Converge 2027)
  enableConverge2027Preview: boolean;

  // Campus Projects & Giving
  enableGivingPortals: boolean;
}

export const featureFlags: FeatureFlags = {
  enableConverge2027Preview: env.VITE_ENABLE_CONVERGE_2027_PREVIEW === 'true',
  enableGivingPortals: true,
};

/**
 * Helper to determine if registration/checkout is open for a specific event
 */
export function isEventRegistrationOpen(slug: string): boolean {
  switch (slug) {
    case 'converge-2027':
      return featureFlags.enableConverge2027Preview;
    default:
      return false;
  }
}
